import React, { useEffect, useMemo, useRef } from 'react';
import { motion, useAnimation } from 'framer-motion';

interface AnimatedTextProps {
  text: string;
  baseDelay?: number; // ms
  randomness?: number; // ms
  punctuationPause?: number; // ms
  onComplete?: () => void;
  className?: string;
  element?: 'span' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'div' | 'li' | 'a';
  preserveWhitespace?: boolean;
}

const punctuationRegex = /[.,!?;:]/;

const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  baseDelay = 40,
  randomness = 20,
  punctuationPause = 150,
  onComplete,
  className = '',
  element = 'span',
  preserveWhitespace = false,
}) => {
  const controls = useAnimation();
  const hasAnimated = useRef(false);

  const chars = useMemo(() => Array.from(text), [text]);

  useEffect(() => {
    // Reset animation state when component mounts
    hasAnimated.current = false;

    const animateSequence = async () => {
      if (hasAnimated.current) return;

      for (let i = 0; i < chars.length; i++) {
        const char = chars[i];
        const prevChar = i > 0 ? chars[i-1] : '';

        // Start animation for this character
        await controls.start(i, { 
          opacity: 1, 
          y: 0,
          transition: { duration: 0.06 }
        });

        // Calculate delay for the next character
        let nextDelay = baseDelay;

        // Add randomness
        nextDelay += (Math.random() * randomness * 2 - randomness);

        // Add pause after punctuation (based on previous character)
        if (punctuationRegex.test(prevChar)) {
          nextDelay += punctuationPause;
        }

        // Occasional longer pause to simulate human typing rhythm
        if (Math.random() > 0.9) {
          nextDelay += 80;
        }

        // Wait before showing the next character
        await new Promise((resolve) => setTimeout(resolve, nextDelay));
      }

      hasAnimated.current = true;

      // Call onComplete after a short delay to ensure all animations are visible
      setTimeout(() => {
        if (onComplete) {
          onComplete();
        }
      }, 50);
    };

    animateSequence();

    return () => {
      controls.stop();
    };
  }, [chars, controls, baseDelay, randomness, punctuationPause, onComplete]);

  // If text is empty, render nothing
  if (!text || text.length === 0) {
    return null;
  }

  const animatedCharacters = chars.map((char, index) => (
    <motion.span
      key={`char-${index}`}
      custom={index}
      initial={{ opacity: 0, y: 3 }}
      animate={controls}
      style={{ 
        display: 'inline-block',
        whiteSpace: 'pre'
      }}
    >
      {char === ' ' ? '\u00A0' : char}
    </motion.span>
  ));

  // Common props for the container element
  const commonProps = {
    className: `animated-text ${className}`,
    style: { 
      whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const,
      display: 'inline-block'
    }
  };

  // Render with the appropriate element type
  switch (element) {
    case 'p':
      return <p {...commonProps}>{animatedCharacters}</p>;
    case 'h1':
      return <h1 {...commonProps}>{animatedCharacters}</h1>;
    case 'h2':
      return <h2 {...commonProps}>{animatedCharacters}</h2>;
    case 'h3':
      return <h3 {...commonProps}>{animatedCharacters}</h3>;
    case 'h4':
      return <h4 {...commonProps}>{animatedCharacters}</h4>;
    case 'div':
      return <div {...commonProps}>{animatedCharacters}</div>;
    case 'li':
      return <li {...commonProps}>{animatedCharacters}</li>;
    case 'a':
      return <a {...commonProps}>{animatedCharacters}</a>;
    case 'span':
    default:
      return <span {...commonProps}>{animatedCharacters}</span>;
  }
};

export default AnimatedText;
